options.styles:
& {
  --grid: #e0533c;
  --home: #3d8bfd;
  --muted: rgba(128, 128, 128, 0.35);
}

/* Drawn on a 440 x 400 grid like the Raggendorf flow; --u is one unit. */
& .dt-row {
  height: 100%;
  padding: 0;
  container-type: size;
}

& .stage {
  --u: calc(min(100cqw, 110cqh) / 440);
  position: relative;
  width: calc(var(--u) * 440);
  height: calc(var(--u) * 400);
  margin: 0 auto;
}

& .stage.stale {
  opacity: 0.4;
}

& .stage > div,
& .stage > a {
  position: absolute;
}

& a {
  color: inherit;
  text-decoration: none;
}

& a:focus-visible {
  outline: 2px solid var(--home);
  outline-offset: 2px;
}

& .updated {
  left: 50%;
  top: 0;
  transform: translateX(-50%);
  font-size: calc(var(--u) * 12);
  opacity: 0.7;
}

& .tag {
  display: flex;
  flex-direction: column;
  align-items: center;
  line-height: 1.25;
  white-space: nowrap;
  transform: translateX(-50%);
  top: calc(var(--u) * 235);
}

& .name {
  font-size: calc(var(--u) * 12);
  opacity: 0.7;
}

& .value {
  font-size: calc(var(--u) * 16);
  font-weight: 600;
}

& .node {
  top: calc(var(--u) * 190);
  width: calc(var(--u) * 52);
  height: calc(var(--u) * 52);
  margin: calc(var(--u) * -26) 0 0 calc(var(--u) * -26);
  box-sizing: border-box;
  border: calc(var(--u) * 2.5) solid;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: calc(var(--u) * 22);
}

& .node.grid, & .tag.grid { left: calc(var(--u) * 110); }
& .node.apartment, & .tag.apartment { left: calc(var(--u) * 330); }
& .node.grid { border-color: var(--grid); }
& .node.apartment { border-color: var(--home); }

& .node.off {
  border-color: var(--muted);
  filter: grayscale(1);
  opacity: 0.6;
}

/* The line runs from the grid to the apartment; moving dots while the
   room is below its setpoint. */
& .line {
  left: calc(var(--u) * 136);
  top: calc(var(--u) * 190);
  width: calc(var(--u) * 168);
  height: calc(var(--u) * 3.5);
  margin-top: calc(var(--u) * -1.75);
  border-radius: 999px;
  --c: var(--grid);
  background: var(--muted);
}

& .line.on {
  background:
    radial-gradient(circle, var(--c) 40%, transparent 45%) 0 50% / calc(var(--u) * 10) 100% repeat-x,
    linear-gradient(color-mix(in srgb, var(--c) 35%, transparent), color-mix(in srgb, var(--c) 35%, transparent));
  animation: energy-flow 0.8s linear infinite;
}

@keyframes energy-flow {
  from { background-position: 0 50%, 0 0; }
  to { background-position: calc(var(--u) * 10) 50%, 0 0; }
}

@media (prefers-reduced-motion: reduce) {
  & .line.on { animation: none; }
}

options.afterRender:
const root = context.element.querySelector('.side');
const time = root.querySelector('.time');
const date = root.querySelector('.date');
const weather = root.querySelector('.weather');

const tick = () => {
  const now = new Date();
  time.textContent = clockTime(now);
  date.textContent = now.toLocaleDateString([], { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
};

const conditions = {
  0: ['☀️', 'Clear', '🌙'],
  1: ['🌤️', 'Mainly clear', '🌙'],
  2: ['⛅', 'Partly cloudy', '☁️'],
  3: ['☁️', 'Overcast'],
  45: ['🌫️', 'Fog'],
  48: ['🌫️', 'Rime fog'],
  51: ['🌦️', 'Light drizzle'],
  53: ['🌦️', 'Drizzle'],
  55: ['🌧️', 'Dense drizzle'],
  56: ['🌧️', 'Freezing drizzle'],
  57: ['🌧️', 'Freezing drizzle'],
  61: ['🌦️', 'Light rain'],
  63: ['🌧️', 'Rain'],
  65: ['🌧️', 'Heavy rain'],
  66: ['🌧️', 'Freezing rain'],
  67: ['🌧️', 'Freezing rain'],
  71: ['🌨️', 'Light snow'],
  73: ['🌨️', 'Snow'],
  75: ['❄️', 'Heavy snow'],
  77: ['🌨️', 'Snow grains'],
  80: ['🌦️', 'Light showers'],
  81: ['🌧️', 'Showers'],
  82: ['⛈️', 'Violent showers'],
  85: ['🌨️', 'Snow showers'],
  86: ['🌨️', 'Heavy snow showers'],
  95: ['⛈️', 'Thunderstorm'],
  96: ['⛈️', 'Thunderstorm, hail'],
  99: ['⛈️', 'Thunderstorm, hail'],
};
const icon = (code, day = 1) => {
  const c = conditions[code] || ['❔'];
  return day || !c[2] ? c[0] : c[2];
};
const label = (code) => (conditions[code] || [, 'Unknown'])[1];
const compass = (deg) => ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'][Math.round(deg / 45) % 8];
const round = (v) => Math.round(v);
const clockTime = (t) => new Date(t).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
const rain = (amount, probability) => [
  amount >= 0.05 ? amount.toFixed(1) + ' mm' : '',
  probability >= 10 ? probability + ' %' : '',
].filter(Boolean).join(' · ');

const url = 'https://api.open-meteo.com/v1/forecast?@@OPEN_METEO_LOCATION_PODERSDORF@@'
  + '&timezone=auto&timeformat=unixtime&forecast_days=5&forecast_hours=24'
  + '&current=temperature_2m,apparent_temperature,relative_humidity_2m,weather_code,is_day,precipitation,wind_speed_10m,wind_gusts_10m,wind_direction_10m'
  + '&hourly=temperature_2m,weather_code,is_day,precipitation_probability,precipitation'
  + '&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_sum,precipitation_probability_max';
const cache = window.homeWeatherPodersdorf || (window.homeWeatherPodersdorf = {});

const load = async () => {
  const wait = (cache.data ? 15 : 1) * 60000;
  if (!cache.pending && Date.now() - (cache.tried || 0) > wait) {
    cache.tried = Date.now();
    cache.pending = fetch(url)
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error(r.status + ' ' + r.statusText))))
      .then((d) => { cache.data = d; cache.error = null; })
      .catch((e) => { cache.error = e.message; })
      .finally(() => { cache.pending = null; });
  }
  await cache.pending;
  return cache.data;
};

const draw = (d) => {
  const c = d.current;
  const h = d.hourly;
  const dd = d.daily;
  const hours = [];
  for (let i = 2; i < h.time.length; i += 3) {
    hours.push(`<div class="hour">
      <span class="muted">${clockTime(h.time[i] * 1000)}</span>
      <span class="icon">${icon(h.weather_code[i], h.is_day[i])}</span>
      <span class="t">${round(h.temperature_2m[i])}°</span>
      <span class="rain">${rain(0, h.precipitation_probability[i])}</span>
    </div>`);
  }
  const days = dd.time.map((t, i) => `<div class="day">
      <span class="name">${i === 0 ? 'Today' : new Date(t * 1000).toLocaleDateString([], { weekday: 'short' })}</span>
      <span class="icon">${icon(dd.weather_code[i])}</span>
      <span class="cond muted">${label(dd.weather_code[i])}</span>
      <span class="t"><b>${round(dd.temperature_2m_max[i])}°</b> <span class="muted">${round(dd.temperature_2m_min[i])}°</span></span>
      <span class="rain">${rain(dd.precipitation_sum[i], dd.precipitation_probability_max[i])}</span>
    </div>`);
  weather.innerHTML = `<div class="now ${cache.error ? 'stale' : ''}">
      <span class="icon">${icon(c.weather_code, c.is_day)}</span>
      <span class="temp">${round(c.temperature_2m)}°</span>
      <span class="details">
        <span class="cond">${label(c.weather_code)}</span>
        <span>Feels like ${round(c.apparent_temperature)}° · ${c.relative_humidity_2m} %</span>
        <span>Wind ${round(c.wind_speed_10m)} km/h ${compass(c.wind_direction_10m)}, gusts ${round(c.wind_gusts_10m)}</span>
        <span class="rain">${c.precipitation > 0 ? c.precipitation.toFixed(1) + ' mm now' : ''}</span>
      </span>
    </div>
    <div class="hours">${hours.join('')}</div>
    <div class="days">${days.join('')}</div>
    <div class="source muted">Open-Meteo, ${clockTime(c.time * 1000)}${cache.error ? ' · update failed: ' + cache.error : ''}</div>`;
};

const update = async () => {
  const d = await load();
  if (d) {
    draw(d);
  } else if (cache.error) {
    weather.innerHTML = `<div class="note">No weather: ${cache.error}</div>`;
  }
};

tick();
update();
const clockTimer = setInterval(tick, 1000);
const weatherTimer = setInterval(update, 60000);

return () => {
  clearInterval(clockTimer);
  clearInterval(weatherTimer);
};

options.styles:
& {
  --rain: #3d8bfd;
}

& .dt-row {
  height: 100%;
  padding: 0;
}

& .side {
  height: 100%;
  container-type: size;
  display: flex;
  flex-direction: column;
  gap: 1.5cqh;
  text-align: center;
  overflow: hidden;
}

& .time {
  font-size: min(24cqw, 17cqh);
  font-weight: 600;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

& .date {
  font-size: min(6cqw, 4.5cqh);
  opacity: 0.8;
}

& .weather {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  justify-content: space-evenly;
  gap: 1.5cqh;
  font-size: min(3.6cqw, 2.8cqh);
}

& .muted {
  opacity: 0.7;
}

& .rain {
  color: var(--rain);
}

& .stale {
  opacity: 0.5;
}

& .now {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3cqw;
}

& .now .icon {
  font-size: min(15cqw, 11cqh);
  line-height: 1;
}

& .now .temp {
  font-size: min(15cqw, 11cqh);
  font-weight: 600;
  line-height: 1;
}

& .now .details {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  text-align: left;
  line-height: 1.35;
}

& .now .cond {
  font-size: 1.4em;
  font-weight: 600;
}

& .hours {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
}

& .hour {
  display: flex;
  flex-direction: column;
  align-items: center;
  line-height: 1.3;
}

& .hour .icon {
  font-size: 1.8em;
}

& .hour .t {
  font-weight: 600;
}

& .days {
  display: grid;
  grid-template-columns: auto auto 1fr auto auto;
  column-gap: 2.5cqw;
  row-gap: 0.6cqh;
  align-items: center;
  text-align: left;
  margin-inline: 1em;
}

& .day {
  display: contents;
}

& .day .name {
  font-weight: 600;
}

& .day .icon {
  font-size: 1.5em;
}

& .day .t,
& .day .rain {
  text-align: right;
  white-space: nowrap;
}

& .source,
& .note {
  font-size: 0.8em;
}
